// CAF: stateful actors own their state; the mailbox is internal
struct counter_state { int count; };

behavior counter(stateful_actor<counter_state>* self, int initial) {
  self->state.count = initial;
  return {
    [self](add_atom, int n) { self->state.count += n; },
    [self](get_atom) { return self->state.count; }
  };
}
auto peer = sys.spawn(counter, 0);      // actor handle = address
anon_send(peer, add_atom_v, 1);

