class Actor {
  std::mutex m; std::condition_variable cv;
  std::queue<Msg> inbox; bool done = false;
public:
  void tell(Msg msg) {
    { std::lock_guard lk(m); inbox.push(std::move(msg)); }
    cv.notify_one();
  }
  void run() {                                   // one thread per actor
    for (;;) { std::unique_lock lk(m);
      cv.wait(lk, [&]{ return done || !inbox.empty(); });
      if (inbox.empty() && done) return;
      Msg msg = std::move(inbox.front()); inbox.pop(); lk.unlock();
      handle(msg); }                             // state touched only here
  }
};
